from math import exp, factorial, sin, log

def exp_taylor(x, terms):                      # e^x = sum x^k / k!
    return sum(x ** k / factorial(k) for k in range(terms))

for terms in (2, 3, 5, 10):
    approx = exp_taylor(1, terms)
    print(terms, "số hạng:", round(approx, 6), " sai số:", f"{abs(exp(1) - approx):.2e}")

# Xấp xỉ bậc nhất: log(1 + x) ~ x khi x nhỏ (lợi suất log ~ lợi suất đơn)
for r in (0.01, 0.05, 0.20):
    print("r =", r, " log(1+r) =", round(log(1 + r), 5))
